<?php
require __DIR__.'/../vendor/autoload.php';require __DIR__.'/../includes/report_input_templates.php';
function checkMnj($v,$msg){if(!$v)throw new RuntimeException($msg);}
foreach(['2026-09','2027-01'] as $period){$b=buildReportInputTemplate('MNJ',$period);$s=$b->getSheetByName('MNJ');checkMnj($s!==null,'Missing sheet');checkMnj(str_contains($s->getCell('A1')->getValue(),substr($period,0,4)),'Year');checkMnj($s->getHighestRow()===16,'Only the selected year table');checkMnj($s->getCell('D5')->getValue()===null,'Must be blank');$s->setCellValue('D5',10);$s->setCellValue('E5',20);checkMnj($s->getCell('P5')->getCalculatedValue()==30,'Full year');$s->setCellValue('D6',4);$s->setCellValue('D7',2);checkMnj($s->getCell('D8')->getCalculatedValue()==0.5,'Percentage');foreach(['Xlsx','Ods'] as $type){$p=tempnam(sys_get_temp_dir(),'mnj-test-');try{$w=\PhpOffice\PhpSpreadsheet\IOFactory::createWriter($b,$type);$w->save($p);$r=readMnjInput(base64_encode(file_get_contents($p)),$period);checkMnj($r->getSheetByName('MNJ')->getCell('P5')->getCalculatedValue()==30,'Roundtrip');$r->disconnectWorksheets();try{readMnjInput(base64_encode(file_get_contents($p)),'2030-01');throw new RuntimeException('Wrong period accepted');}catch(InvalidArgumentException $e){}}finally{unlink($p);}}$b->disconnectWorksheets();}
echo "PASS: MNJ blank inputs, years, totals, percentages, XLSX/ODS upload and period validation.\n";
